const _ROWS = BATCH76_KYR6_AMAZON_3P_NUTRICOST;
if (_ROWS.length !== 524) throw new Error('batch76 tally drift: expected 524 rows');
if (_ROWS.filter((r) => r.verdict === 'clean').length !== 198) {
  throw new Error('batch76 Clean tally drift');
}
if (_ROWS.filter((r) => r.verdict === 'caution').length !== 315) {
  throw new Error('batch76 Caution tally drift');
}
if (_ROWS.filter((r) => r.verdict === 'avoid').length !== 11) {
  throw new Error('batch76 Avoid tally drift');
}
if (_ROWS.some((r) => r.recordStatus !== UNVERIFIED)) {
  throw new Error('batch76 recordStatus must stay unverified');
}
if (_ROWS.some((r) => !r.formulaId)) {
  throw new Error('batch76 every row needs formulaId');
}
const _ids = new Set(_ROWS.map((r) => r.id));
if (_ids.size !== _ROWS.length) throw new Error('batch76 duplicate ids');
if (_ROWS.some((r) => r.brand !== BRAND)) {
  throw new Error('batch76 writes Nutricost only');
}
if (_ROWS.some((r) => r.barcode && !/^\d{12}$/.test(r.barcode))) {
  throw new Error('batch76 barcode must be a 12-digit UPC-A');
}
if (_ROWS.some((r) => {
  if (!r.barcode) return false;
  let sum = 0;
  for (let i = 0; i < 11; i++) sum += Number(r.barcode[i]) * (i % 2 === 0 ? 3 : 1);
  return (10 - (sum % 10)) % 10 !== Number(r.barcode[11]);
})) {
  throw new Error('batch76 barcode failed UPC-A check digit');
}
if (_ROWS.filter((r) => r.formulaId !== r.id).length !== 108) {
  throw new Error('batch76 REUSE-formula tally drift');
}
if (_ROWS.some((r) => /toothpaste|essential oil|sprouts|now foods|naturewise|welmate|goodsense/i.test(r.brand + r.productName))) {
  throw new Error('batch76 leftover 3P / Sprouts / toothpaste / NOW must stay out');
}
if (_ROWS.some((r) => /\boil\b/i.test(r.productName) && !/powder|softgel|capsule|gumm|tablet/i.test(r.productName))) {
  throw new Error('batch76 must not grade oil pour bottles');
}
for (const record of _ROWS) {
  if (record.verdict === 'avoid' && !record.inactiveIngredients.some((i) => i.riskLevel === 'high')) {
    throw new Error(`batch76 Avoid without High on ${record.id}`);
  }
  if (record.verdict === 'caution' && !record.inactiveIngredients.some((i) => i.riskLevel === 'limited' || i.riskLevel === 'moderate')) {
    throw new Error(`batch76 Caution without Limited or Moderate on ${record.id}`);
  }
  if (record.verdict === 'clean' && record.inactiveIngredients.some((i) => i.riskLevel !== 'cleared')) {
    throw new Error(`batch76 Clean row has a non-cleared flag on ${record.id}`);
  }
  if (record.form === 'gummy' && record.inactiveIngredients.some((i) => /sunflower oil|palm oil|soybean oil/i.test(i.name) && i.riskLevel !== 'high')) {
    throw new Error(`batch76 gummy seed oil must be High on ${record.id}`);
  }
}
if (BATCH76_OIL_HUNT.length !== 13) {
  throw new Error('batch76 oil pour bottles stay on the hunt list');
}
if (!BATCH76_SKIPPED.some((s) => /protein-aisle/i.test(s.reason))) {
  throw new Error('batch76 must skip protein-aisle');
}
if (!BATCH76_SKIPPED.some((s) => /already|turmeric curcumin 2300|batch54/i.test(s.sku + s.reason))) {
  throw new Error('batch76 must note the batch54 turmeric twin');
}
if (!BATCH76_REFUSED.every((s) => /7-step packet/.test(s.reason) && /NO Search row/.test(s.reason))) {
  throw new Error('batch76 refuses need a 7-step packet and no Search row');
}
